@Test
public void testBasicRunJobForSingleNodeTraining() throws Exception {
    RunJobCli runJobCli = new RunJobCli(RunJobCliParsingCommonTest.getMockClientContext());
    assertFalse(SubmarineLogs.isVerbose());
    runJobCli.run(new String[] { "--framework", "pytorch", "--name", "my-job", "--docker_image", "tf-docker:1.1.0", "--input_path", "hdfs://input", "--checkpoint_path", "hdfs://output", "--num_workers", "1", "--worker_launch_cmd", "python run-job.py", "--worker_resources", "memory=4g,vcores=2", "--verbose", "--wait_job_finish" });
    RunJobParameters jobRunParameters = runJobCli.getRunJobParameters();
    assertTrue(RunJobParameters.class + " must be an instance of " + PyTorchRunJobParameters.class, jobRunParameters instanceof PyTorchRunJobParameters);
    PyTorchRunJobParameters pyTorchParams = (PyTorchRunJobParameters) jobRunParameters;
    assertEquals(jobRunParameters.getInputPath(), "hdfs://input");
    assertEquals(jobRunParameters.getCheckpointPath(), "hdfs://output");
    assertEquals(pyTorchParams.getNumWorkers(), 1);
    assertEquals(pyTorchParams.getWorkerLaunchCmd(), "python run-job.py");
    assertEquals(Resources.createResource(4096, 2), pyTorchParams.getWorkerResource());
    assertTrue(SubmarineLogs.isVerbose());
    assertTrue(jobRunParameters.isWaitJobFinish());
}

