@Test
public void testBasicRunJobForDistributedTraining() throws Exception {
    RunJobCli runJobCli = new RunJobCli(RunJobCliParsingCommonTest.getMockClientContext());
    assertFalse(SubmarineLogs.isVerbose());
    runJobCli.run(new String[] { "--framework", "tensorflow", "--name", "my-job", "--docker_image", "tf-docker:1.1.0", "--input_path", "hdfs://input", "--checkpoint_path", "hdfs://output", "--num_workers", "3", "--num_ps", "2", "--worker_launch_cmd", "python run-job.py", "--worker_resources", "memory=2048M,vcores=2", "--ps_resources", "memory=4G,vcores=4", "--tensorboard", "true", "--ps_launch_cmd", "python run-ps.py", "--keytab", "/keytab/path", "--principal", "user/_HOST@domain.com", "--distribute_keytab", "--verbose" });
    RunJobParameters jobRunParameters = runJobCli.getRunJobParameters();
    assertTrue(RunJobParameters.class + " must be an instance of " + TensorFlowRunJobParameters.class, jobRunParameters instanceof TensorFlowRunJobParameters);
    TensorFlowRunJobParameters tensorFlowParams = (TensorFlowRunJobParameters) jobRunParameters;
    assertEquals(jobRunParameters.getInputPath(), "hdfs://input");
    assertEquals(jobRunParameters.getCheckpointPath(), "hdfs://output");
    assertEquals(tensorFlowParams.getNumPS(), 2);
    assertEquals(tensorFlowParams.getPSLaunchCmd(), "python run-ps.py");
    assertEquals(Resources.createResource(4096, 4), tensorFlowParams.getPsResource());
    assertEquals(tensorFlowParams.getWorkerLaunchCmd(), "python run-job.py");
    assertEquals(Resources.createResource(2048, 2), tensorFlowParams.getWorkerResource());
    assertEquals(jobRunParameters.getDockerImageName(), "tf-docker:1.1.0");
    assertEquals(jobRunParameters.getKeytab(), "/keytab/path");
    assertEquals(jobRunParameters.getPrincipal(), "user/_HOST@domain.com");
    assertTrue(jobRunParameters.isDistributeKeytab());
    assertTrue(SubmarineLogs.isVerbose());
}

